sys_ws_operation.operation_script:
(function process(request, response) {
  function safeDurationDays(d1, d2) {
    if (!d1 || !d2) return 1;
    try {
      var s = new GlideDateTime(d1);
      var e = new GlideDateTime(d2);
      var diff = GlideDateTime.subtract(s, e);
      if (diff) {
        var ms = Math.abs(diff.getNumericValue());
        return Math.max(1, Math.ceil(ms / 86400000));
      }
    } catch (ex) {}
    return 1;
  }

  function safeCompare(d1, d2) {
    if (!d1 || !d2) return 0;
    try {
      var g1 = new GlideDateTime(d1);
      var g2 = new GlideDateTime(d2);
      return g1.compareTo(g2);
    } catch (ex) {
      return 0;
    }
  }

  try {
    var SCHED = "x_2056099_indust_0_prod_sched";
    var PO = "x_2056099_indust_0_production_order";
    var RES = "x_2056099_indust_0_prod_res";
    var CO = "x_2056099_indust_0_cust_order";
    var PM = "x_2056099_indust_0_production_material";
    var STOCK = "x_2056099_indust_0_inv_stock";

    // ── 1. Load all active resources ──
    var resMap = {};
    var resGr = new GlideRecord(RES);
    resGr.addQuery("active", true);
    resGr.query();
    var resources = [];
    while (resGr.next()) {
      var r = {
        sys_id: resGr.getValue("sys_id"),
        name: resGr.getValue("resource_name"),
        resource_id: resGr.getValue("resource_id"),
        resource_type: resGr.getDisplayValue("resource_type"),
        status: resGr.getValue("status"),
        statusDisplay: resGr.getDisplayValue("status"),
        capacity_per_day: parseFloat(resGr.getValue("capacity_per_day")) || 0,
        efficiency: parseFloat(resGr.getValue("efficiency_percentage")) || 100,
        maintenance_required: resGr.getValue("maintenance_required") == "1",
        scheduled_days: 0
      };
      resMap[r.sys_id] = r;
      resources.push(r);
    }

    // ── 2. Load all active schedules ──
    var schedGr = new GlideRecord(SCHED);
    schedGr.addQuery("active", true);
    schedGr.addQuery("status", "IN", "draft,scheduled,confirmed,in_progress");
    schedGr.orderBy("planned_start");
    schedGr.query();

    var schedules = [];
    while (schedGr.next()) {
      var startVal = schedGr.getValue("planned_start");
      var endVal = schedGr.getValue("planned_end");
      var durDays = safeDurationDays(startVal, endVal);

      schedules.push({
        sys_id: schedGr.getValue("sys_id"),
        number: schedGr.getValue("number"),
        po_id: schedGr.getValue("production_order"),
        po_display: schedGr.getDisplayValue("production_order"),
        res_id: schedGr.getValue("production_resource"),
        res_display: schedGr.getDisplayValue("production_resource"),
        planned_start: schedGr.getDisplayValue("planned_start") || startVal || "",
        planned_start_val: startVal || "",
        planned_end: schedGr.getDisplayValue("planned_end") || endVal || "",
        planned_end_val: endVal || "",
        planned_quantity: parseFloat(schedGr.getValue("planned_quantity")) || 0,
        status: schedGr.getValue("status"),
        statusDisplay: schedGr.getDisplayValue("status"),
        priority: schedGr.getValue("priority"),
        priorityDisplay: schedGr.getDisplayValue("priority"),
        duration_days: durDays
      });
    }

    // ── 3. Enrich with PO, resource health, delivery, conflicts ──
    var resSched = {};
    for (var i = 0; i < schedules.length; i++) {
      var s = schedules[i];
      if (!resSched[s.res_id]) resSched[s.res_id] = [];
      resSched[s.res_id].push(s);
      if (resMap[s.res_id]) resMap[s.res_id].scheduled_days += s.duration_days;
    }

    var poCache = {};
    function getPO(poId) {
      if (!poId) return null;
      if (poCache[poId]) return poCache[poId];
      var gr = new GlideRecord(PO);
      if (gr.get(poId)) {
        poCache[poId] = {
          sys_id: poId,
          number: gr.getValue("number"),
          status: gr.getValue("status"),
          statusDisplay: gr.getDisplayValue("status"),
          finished_product: gr.getDisplayValue("finished_product"),
          priority: gr.getValue("priority"),
          customer_order: gr.getValue("customer_order"),
          planned_end_date: gr.getValue("planned_end_date") || gr.getValue("planned_completion_date"),
          quantity_planned: parseFloat(gr.getValue("quantity_planned")) || 0,
          required_capacity_per_day: parseFloat(gr.getValue("required_capacity_per_day")) || 0
        };
      }
      return poCache[poId] || null;
    }

    var coCache = {};
    function getDeliveryDate(coId) {
      if (!coId) return null;
      if (coCache[coId] !== undefined) return coCache[coId];
      var gr = new GlideRecord(CO);
      if (gr.get(coId)) {
        coCache[coId] = gr.getValue("requested_delivery_date") || gr.getValue("required_delivery_date") || null;
      } else {
        coCache[coId] = null;
      }
      return coCache[coId];
    }

    var enriched = [];
    for (var j = 0; j < schedules.length; j++) {
      var sc = schedules[j];
      var po = getPO(sc.po_id);
      var res = resMap[sc.res_id] || null;
      var health = [];

      // Resource feasibility
      var resFeasible = "feasible";
      if (!res) {
        resFeasible = "resource_unavailable";
        health.push("Resource not found");
      } else {
        if (res.status !== "available") {
          resFeasible = res.maintenance_required ? "maintenance" : "resource_unavailable";
          health.push("Resource " + res.statusDisplay);
        }
        if (res.maintenance_required) {
          resFeasible = "maintenance";
          health.push("Maintenance required");
        }
        if (res.capacity_per_day <= 0) {
          resFeasible = "capacity_shortage";
          health.push("Zero capacity");
        } else if (po && po.required_capacity_per_day > 0 && po.required_capacity_per_day > res.capacity_per_day) {
          resFeasible = "capacity_shortage";
          health.push("Required " + po.required_capacity_per_day + "/day > capacity " + res.capacity_per_day + "/day");
        }
      }

      // Conflict detection (overlapping schedules on same resource)
      var conflicts = [];
      var resList = resSched[sc.res_id] || [];
      for (var k = 0; k < resList.length; k++) {
        var other = resList[k];
        if (other.sys_id === sc.sys_id) continue;
        var oStart = other.planned_start_val;
        var oEnd = other.planned_end_val;
        var sStart = sc.planned_start_val;
        var sEnd = sc.planned_end_val;
        if (sStart && sEnd && oStart && oEnd) {
          if (safeCompare(sStart, oEnd) < 0 && safeCompare(sEnd, oStart) > 0) {
            conflicts.push(other.number);
          }
        }
      }
      if (conflicts.length > 0) {
        health.push("Overlaps with " + conflicts.join(", "));
      }

      // Delivery feasibility
      var deliveryDate = null;
      var deliveryDisplay = null;
      var deliveryStatus = "not_checked";
      if (po && po.customer_order) {
        var dd = getDeliveryDate(po.customer_order);
        if (dd) {
          deliveryDate = dd;
          var ddGdt = new GlideDateTime(dd);
          deliveryDisplay = ddGdt.getDisplayValue();
          var schedEnd = sc.planned_end_val;
          if (schedEnd && safeCompare(schedEnd, dd) > 0) {
            deliveryStatus = "delivery_risk";
            var delayDays = safeDurationDays(dd, schedEnd);
            health.push("Delivery risk: " + delayDays + " day(s) late");
          } else {
            deliveryStatus = "on_time";
          }
        } else {
          deliveryStatus = "no_date";
        }
      } else if (po && po.planned_end_date) {
        var poEnd = new GlideDateTime(po.planned_end_date);
        deliveryDisplay = poEnd.getDisplayValue();
        var sEnd2 = sc.planned_end_val;
        if (sEnd2 && safeCompare(sEnd2, po.planned_end_date) > 0) {
          deliveryStatus = "delivery_risk";
          health.push("Past PO planned end date");
        } else {
          deliveryStatus = "on_time";
        }
      }

      // Overall health status
      var overallHealth = "feasible";
      if (conflicts.length > 0) overallHealth = "conflict";
      else if (resFeasible === "maintenance") overallHealth = "maintenance";
      else if (resFeasible === "resource_unavailable") overallHealth = "resource_unavailable";
      else if (resFeasible === "capacity_shortage") overallHealth = "capacity_shortage";
      else if (deliveryStatus === "delivery_risk") overallHealth = "delivery_risk";

      enriched.push({
        sys_id: sc.sys_id,
        number: sc.number,
        status: sc.status,
        statusDisplay: sc.statusDisplay,
        priority: sc.priority,
        priorityDisplay: sc.priorityDisplay,
        planned_start: sc.planned_start,
        planned_end: sc.planned_end,
        planned_quantity: sc.planned_quantity,
        duration_days: sc.duration_days,
        po_id: sc.po_id,
        po_number: po ? po.number : "",
        po_status: po ? po.statusDisplay : "",
        finished_product: po ? po.finished_product : "",
        res_id: sc.res_id,
        res_name: sc.res_display,
        res_type: res ? res.resource_type : "",
        res_status: res ? res.statusDisplay : "",
        resource_feasibility: resFeasible,
        delivery_date: deliveryDisplay,
        delivery_status: deliveryStatus,
        conflicts: conflicts,
        health: overallHealth,
        health_details: health
      });
    }

    // ── 4. Unscheduled POs ──
    var unscheduledPOs = [];
    var poGr = new GlideRecord(PO);
    poGr.addQuery("active", true);
    poGr.addQuery("status", "IN", "draft,planned,material_check,materials_reserved");
    poGr.query();
    while (poGr.next()) {
      var poid = poGr.getValue("sys_id");
      var hasSchedule = false;
      for (var m = 0; m < schedules.length; m++) {
        if (schedules[m].po_id === poid) { hasSchedule = true; break; }
      }
      if (!hasSchedule) {
        unscheduledPOs.push({
          sys_id: poid,
          number: poGr.getValue("number"),
          status: poGr.getValue("status"),
          statusDisplay: poGr.getDisplayValue("status"),
          finished_product: poGr.getDisplayValue("finished_product"),
          priority: poGr.getValue("priority"),
          priorityDisplay: poGr.getDisplayValue("priority"),
          quantity_planned: parseFloat(poGr.getValue("quantity_planned")) || 0
        });
      }
    }

    // ── 5. Summary ──
    var feasibleCount = 0, conflictCount = 0, riskCount = 0;
    for (var n = 0; n < enriched.length; n++) {
      if (enriched[n].health === "feasible") feasibleCount++;
      else if (enriched[n].health === "conflict") conflictCount++;
      else riskCount++;
    }

    var payload = {
      success: true,
      schedules: enriched,
      resources: resources,
      unscheduledOrders: unscheduledPOs,
      summary: {
        totalSchedules: enriched.length,
        feasible: feasibleCount,
        conflicts: conflictCount,
        risks: riskCount,
        totalResources: resources.length,
        unscheduledOrders: unscheduledPOs.length
      }
    };

    response.setStatus(200);
    response.setBody(payload);

  } catch (err) {
    gs.error("Schedule Planner Data API error: " + err.message);
    var fallback = {
      success: true,
      schedules: [],
      resources: [],
      unscheduledOrders: [],
      summary: {
        totalSchedules: 0,
        feasible: 0,
        conflicts: 0,
        risks: 0,
        totalResources: 0,
        unscheduledOrders: 0
      },
      warning: String(err.message || err)
    };
    response.setStatus(200);
    response.setBody(fallback);
  }
})(request, response);
